	private static void assertUnorderedPageEquals(String id, List<JsonNode> actual, List<JsonNode> expected) {
		assertThat(withoutRows(actual)).as(id + " metadata").containsExactlyElementsOf(withoutRows(expected));
		assertThat(pageRows(actual)).as(id + " statement bag").containsExactlyInAnyOrderElementsOf(pageRows(expected));
	}

	private static List<JsonNode> withoutRows(List<JsonNode> records) {
		return records.stream()
				.filter(record -> !"rows".equals(record.path("type").asText()))
				.map(record -> {
					if (!"metadata".equals(record.path("type").asText())) {
						return record;
					}
					JsonNode normalized = record.deepCopy();
					((ObjectNode) normalized.path("values")).remove("query-request-id");
					return normalized;
				})
				.toList();
	}

	private static List<JsonNode> pageRows(List<JsonNode> records) {
		List<JsonNode> result = new ArrayList<>();
		records.stream()
				.filter(record -> "rows".equals(record.path("type").asText()))
				.forEach(record -> record.path("values").forEach(result::add));
		return result;
	}

	private static ClassicCases verifyClassicQueries(boolean adjacency, CapturedSailRepository nativeRepository,
			Repository reference)
			throws Exception {
		Path output = artifacts(adjacency).resolve("classic-bridge.stderr.log");
		List<String> cases = new ArrayList<>();
		List<String> exploreLinks = new ArrayList<>();
		for (String resource : List.of("<" + NS + "focus>", "<_:focus>", "<" + NS + "unknown>")) {
			JsonNode generated;
			try (TestProcess child = TestProcess.start(
					new ProcessBuilder(Path.of("target", "node", "node").toAbsolutePath().toString(),
							"src/test/frontend/classic/fixtures/native-generated-query-bridge.cjs",
							JSON.writeValueAsString(Map.of("graph", NS + "graph", "resource", resource)))
									.redirectError(ProcessBuilder.Redirect.appendTo(output.toFile())))) {
				Process bridge = child.process();
				generated = JSON.readTree(bridge.getInputStream());
				assertThat(bridge.waitFor()).as("render the actual classic producer queries").isZero();
			}
			for (String name : List.of("resource", "graph", "editor")) {
				String query = generated.path(name).asText();
				List<String> variants = "resource".equals(name)
						? List.of(query, new PagedQuery(query, QueryLanguage.SPARQL, 2, 1).toString())
						: List.of(query);
				for (int variant = 0; variant < variants.size(); variant++) {
					String text = variants.get(variant);
					try (RepositoryConnection connection = nativeRepository.getConnection();
							RepositoryConnection baseline = reference.getConnection()) {
						Query prepared = connection.prepareQuery(text);
						((SailQuery) prepared).setLmdbResultCacheRequested(false);
						Explanation explanation = prepared.explain(Explanation.Level.Telemetry);
						String id = "classic-" + name + "-" + resource.hashCode() + "-" + variant;
						cases.add(id);
						WorkbenchNativeQueryAssertions.writeEvidence(artifacts(adjacency), id, text,
								Map.of("producer", "rendered classic controls and shipped YASQE default",
										"resource", resource, "resultCacheRequested", false),
								explanation);
						if (prepared instanceof TupleQuery tuple) {
							assertTupleQueryMatches(tuple, (SailTupleQuery) baseline.prepareTupleQuery(text));
						} else {
							assertThat(QueryResults.asList(connection.prepareGraphQuery(text).evaluate()))
									.containsExactlyInAnyOrderElementsOf(
											QueryResults.asList(baseline.prepareGraphQuery(text).evaluate()));
						}
						WorkbenchNativeQueryAssertions.assertEfficientExecutedPlan(explanation, id);
					}
				}
			}
			String sectionLink = generated.path("section").asText();
			assertThat(sectionLink).startsWith("explore?resource=");
			exploreLinks.add(sectionLink);
			String linkedResource = URLDecoder.decode(sectionLink.substring("explore?resource=".length()),
					StandardCharsets.UTF_8);
			String id = "classic-explore-section-link-" + resource.hashCode();
			nativeRepository.currentFamily = id;
			Page linked = new Page(id, "explore", ExploreServlet::new, Map.of("resource", linkedResource));
			List<JsonNode> actual = run(linked, nativeRepository);
			List<JsonNode> expected = run(linked, reference);
			assertThat(actual).as("the actual Explore section resource link resolves through the metadata route")
					.containsExactlyElementsOf(expected);
			JsonNode metadata = actual.stream()
					.filter(record -> "metadata".equals(record.path("type").asText()))
					.findFirst()
					.orElseThrow()
					.path("values");
			assertThat(metadata.path("explore-resource").asText()).isEqualTo(linkedResource);
			assertThat(pageRows(actual)).as("the linked Explore metadata route contains no whole-store rows").isEmpty();
		}
		return new ClassicCases(cases, exploreLinks);
	}

	private static void assertTupleQueryMatches(TupleQuery actualQuery, SailTupleQuery referenceQuery) {
		List<BindingSet> actual = QueryResults.asList(actualQuery.evaluate());
		TupleExpr expression = referenceQuery.getParsedQuery().getTupleExpr();
		TupleExpr root = expression instanceof QueryRoot queryRoot ? queryRoot.getArg() : expression;
		if (root instanceof Slice slice) {
			// These real classic generators have no ORDER BY. LIMIT/OFFSET specifies a legal subset, while the
			// particular rows may differ between efficient native strategies and the generic index iterator.
			referenceQuery.getParsedQuery().setTupleExpr(slice.getArg());
			List<BindingSet> complete = QueryResults.asList(referenceQuery.evaluate());
			long available = Math.max(0L, complete.size() - Math.max(0L, slice.getOffset()));
			assertThat(actual).hasSize((int) (slice.hasLimit() ? Math.min(available, slice.getLimit()) : available));
			Map<BindingSet, Long> allowed = WorkbenchNativeQueryAssertions.bag(complete);
			WorkbenchNativeQueryAssertions.bag(actual)
					.forEach((row, count) -> assertThat(count)
							.as("legal unordered classic result multiplicity: %s", row)
							.isLessThanOrEqualTo(allowed.getOrDefault(row, 0L)));
		} else {
			assertThat(actual).containsExactlyInAnyOrderElementsOf(QueryResults.asList(referenceQuery.evaluate()));
		}
	}

	private static TupleQuery prepare(RepositoryConnection connection, CapturedQuery capture) {
		TupleQuery query = connection.prepareTupleQuery(capture.language(), capture.text(), capture.baseURI());
		query.setIncludeInferred(capture.query().getIncludeInferred());
		query.setDataset(capture.query().getDataset());
		capture.query().getBindings().forEach(binding -> query.setBinding(binding.getName(), binding.getValue()));
		// Page producers deliberately request cached results. Admission evidence must evaluate the underlying plan.
		((SailQuery) query).setLmdbResultCacheRequested(false);
		return query;
	}

	private void persist(boolean adjacency, String id, CapturedQuery capture, Explanation explanation)
			throws IOException {
		Path destination = artifacts(adjacency);
		Files.writeString(destination.resolve(id + ".rq"), capture.text());
		Files.writeString(destination.resolve(id + ".json"), explanation.toJson());
		Map<String, String> bindings = new LinkedHashMap<>();
		capture.query()
				.getBindings()
				.forEach(binding -> bindings.put(binding.getName(),
						NTriplesUtil.toNTriplesString(binding.getValue())));
		Map<String, Object> settings = new LinkedHashMap<>();
		settings.put("includeInferred", capture.query().getIncludeInferred());
		settings.put("bindings", bindings);
		settings.put("dataset", capture.query().getDataset() == null ? null
				: Map.of(
						"defaultGraphs",
						capture.query().getDataset().getDefaultGraphs().stream().map(Value::stringValue).toList(),
						"namedGraphs",
						capture.query().getDataset().getNamedGraphs().stream().map(Value::stringValue).toList()));
		settings.put("nativeEvaluation", true);
		settings.put("tripleIndexes", "default: spoc,posc");
		settings.put("directAdjacency", adjacency);
		settings.put("resultCacheRequested", false);
		Files.writeString(destination.resolve(id + "-settings.json"), JSON.writeValueAsString(settings));
	}

	private static Path artifacts(boolean adjacency) throws IOException {
		Path destination = Path.of("..", "..", "logs", "workbench-native-fast-paths", "java-pages",
				adjacency ? "adjacency-native" : "lmdb-native");
		Files.createDirectories(destination);
		return destination;
	}

	private record Page(String id, String route, Supplier<TransformationServlet> servlet, Map<String, String> params) {
	}

	private static List<Page> pages() {
		List<Page> pages = new ArrayList<>();
		pages.add(new Page("types-list", "types", TypesServlet::new, Map.of()));
		pages.add(new Page("types-filter", "types", TypesServlet::new, Map.of("filter", "TYPE")));
		pages.add(new Page("types-counts", "types", TypesServlet::new, Map.of("counts", "true")));
		pages.add(new Page("contexts-list", "contexts", ContextsServlet::new, Map.of()));
		pages.add(new Page("contexts-counts", "contexts", ContextsServlet::new, Map.of("counts", "true")));
		pages.add(new Page("contexts-filter-counts", "contexts", ContextsServlet::new,
				Map.of("counts", "true", "filter", "graph")));
		pages.add(new Page("summary-counts", "summary", SummaryServlet::new, Map.of("counts", "true")));
		pages.add(new Page("clear-list", "clear", ClearServlet::new, Map.of()));
		pages.add(new Page("clear-counts", "clear", ClearServlet::new, Map.of("counts", "true")));
		pages.add(new Page("export-preview", "export", ExportServlet::new, Map.of("action", "preview")));
		pages.add(new Page("namespace-list", "namespaces", NamespacesServlet::new, Map.of()));
		addExploreSectionPages(pages);
		List<Map<String, String>> scopes = List.of(Map.of(), Map.of("context", ""),
				Map.of("context", "<" + NS + "graph>"), Map.of("context", "<_:graph>"));
		for (int scope = 0; scope < scopes.size(); scope++) {
			for (int mask = 0; mask < 8; mask++) {
				Map<String, String> params = new LinkedHashMap<>(scopes.get(scope));
				if ((mask & 1) != 0) {
					params.put("subj", "<" + NS + "focus>");
				}
				if ((mask & 2) != 0) {
					params.put("pred", "<" + NS + "predicate>");
				}
				if ((mask & 4) != 0) {
					params.put("obj", "\"quoted \\\" text\"@en");
				}
				params.put("count", "true");
				pages.add(new Page("remove-counts-scope-" + scope + "-mask-" + mask, "remove", RemoveServlet::new,
						Map.copyOf(params)));
				params.remove("count");
				params.put("preview", "true");
				pages.add(new Page("remove-preview-scope-" + scope + "-mask-" + mask, "remove", RemoveServlet::new,
						Map.copyOf(params)));
			}
		}
		return pages;
	}

	private static void addExploreSectionPages(List<Page> pages) {
		String resource = "<" + NS + "focus>";
		List<String> sections = List.of("outgoing", "incoming", "predicate", "graph", "types", "superClasses",
				"subClasses", "properties", "superProperties", "subProperties", "domain", "range", "label", "comment");
		for (String section : sections) {
			Map<String, String> params = new LinkedHashMap<>();
			params.put("resource", resource);
			params.put("section", section);
			params.put("kind", "rows");
			if ("label".equals(section) || "comment".equals(section)) {
				params.put("language", "en");
			}
			if ("outgoing".equals(section)) {
				params.put("load", "more");
			}
			pages.add(new Page("explore-section-rows-" + section, "explore", ExploreServlet::new,
					Map.copyOf(params)));
		}

		for (String section : List.of("outgoing", "incoming", "predicate")) {
			for (String scope : List.of("default", "named")) {
				pages.add(new Page("explore-section-count-" + section + "-" + scope, "explore", ExploreServlet::new,
						Map.of("resource", resource, "section", section, "kind", "count", "scope", scope)));
			}
		}
		pages.add(new Page("explore-section-count-graph", "explore", ExploreServlet::new,
				Map.of("resource", resource, "section", "graph", "kind", "count", "scope", "named")));
		for (String section : List.of("types", "subClasses")) {
			pages.add(new Page("explore-section-count-" + section, "explore", ExploreServlet::new,
					Map.of("resource", resource, "section", section, "kind", "count")));
		}

		for (String alternateResource : List.of("<_:focus>", "\"quoted \\\" text\"@en",
				"\"42\"^^<http://www.w3.org/2001/XMLSchema#int>", "<" + RDF4J.NIL + ">", "<" + NS + "unknown>",
				"native:focus")) {
			pages.add(
					new Page("explore-section-resource-" + alternateResource.hashCode(), "explore", ExploreServlet::new,
							Map.of("resource", alternateResource, "section", "outgoing", "kind", "rows")));
		}
	}

	private static List<JsonNode> run(Page page, Repository repository) throws Exception {
		TransformationServlet servlet = page.servlet().get();
		servlet.setRepository(repository);
		servlet.setRepositoryManager(mock(RepositoryManager.class));
		RepositoryInfo info = new RepositoryInfo();
		info.setId("workbench-native");
		servlet.setRepositoryInfo(info);
		servlet.init(TestServletConfig.withParams(page.route(), "cookie-max-age", "300", "default-offset", "0",
				"default-know_total", "0"));
		try {
			MockHttpServletRequest request = new MockHttpServletRequest("GET", "/" + page.route());
			request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
			page.params().forEach(request::addParameter);
			MockHttpServletResponse response = new MockHttpServletResponse();
			servlet.service(request, response);
			List<JsonNode> records = new ArrayList<>();
			for (String line : response.getContentAsString().lines().toList()) {
				records.add(JSON.readTree(line));
			}
			assertThat(records).as(page.id()).noneMatch(node -> "error".equals(node.path("type").asText()));
			return records;
		} finally {
			servlet.destroy();
		}
	}

	private static void load(SailRepository repository) {
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			var values = connection.getValueFactory();
			IRI focus = values.createIRI(NS, "focus");
			IRI predicate = values.createIRI(NS, "predicate");
			IRI graph = values.createIRI(NS, "graph");
			Resource blank = values.createBNode("focus");
			connection.begin();
			connection.setNamespace("native", NS);
			connection.add(focus, RDF.TYPE, values.createIRI(NS, "Type"));
			connection.add(focus, RDF.TYPE, values.createIRI(NS, "Type"), graph);
			connection.add(blank, RDF.TYPE, values.createBNode("type"), values.createBNode("graph"));
			connection.add(focus, predicate, values.createLiteral("quoted \" text", "en"));
			connection.add(focus, predicate, values.createLiteral(42), graph);
			connection.add(focus, focus, focus, focus);
			connection.add(blank, predicate, focus, graph);
			connection.add(values.createIRI(NS, "other"), focus, blank);
			connection.add(values.createIRI(NS, "graphSubject"), predicate, focus, blank);
			connection.add(focus, RDFS.LABEL, values.createLiteral("Focus", "en"));
			connection.add(focus, RDFS.LABEL, values.createLiteral("Fokus", "de"), graph);
			connection.add(focus, RDFS.COMMENT, values.createLiteral("A native query fixture."));
			connection.commit();
		}
		try (InferencerConnection connection = (InferencerConnection) repository.getSail().getConnection()) {
			var values = repository.getValueFactory();
			IRI focus = values.createIRI(NS, "focus");
			IRI predicate = values.createIRI(NS, "predicate");
			connection.begin();
			connection.addInferredStatement(focus, RDF.TYPE, values.createIRI(NS, "InferredType"));
			connection.addInferredStatement(focus, predicate, values.createLiteral("inferred", "nb"),
					values.createIRI(NS, "graph"));
			connection.addInferredStatement(values.createBNode("focus"), predicate, values.createLiteral(7),
					values.createBNode("graph"));
			connection.commit();
		}
	}

